properties.outputSchema:
{
  "type": "array",
  "items": {
    "type": "object",
    "properties": {
      "ouuid": {
        "type": "string",
        "description": "The news's unique ID"
      },
      "title_fr": {
        "type": "string",
        "description": "The news's title in french"
        
      },
      "title_nl": {
        "type": "string",
        "description": "The news's title in dutch"
      },
      "publication_date": {
        "type": "date"
      }
    },
    "required": [
      "_id", "publication_date", "title_fr", "title_nl"
    ],
    "additionalProperties": false
  }
}

properties.response:
{%- set searchResult = emsco_search(environment|default('live')|emsco_get_environment.alias, contentTypes: ['news'], size: 10, from: (page * 10), sort: {'publication_date': 'DESC'}) -%}
{{- searchResult.getDocuments()|map(p => { 
    ouuid: p.id, 
    publication_date: p.getData()['publication_date'],
    title_fr: p.getData()['fr']['title'],
    title_nl: p.getData()['nl']['title'],
})|json_encode|raw -}}
